// Package render finalizes provider output: generated headers, checksums,
// preserved custom blocks, overwrite safety, and writing files to disk.
package render

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"path"
	"reflect"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"go.yaml.in/yaml/v3"

	"github.com/amitpatole/renvoy/internal/providers"
)

const (
	// HeaderLine is the first line of every generated file (after the comment prefix).
	HeaderLine = "Code generated by Renvoy; DO NOT EDIT."
	// BeginMarker opens a custom block.
	BeginMarker = "renvoy:begin custom"
	// EndMarker closes a custom block.
	EndMarker = "renvoy:end custom"

	checksumLabel  = "Checksum:"
	checksumPrefix = "sha256:"
)

// CustomBlock returns an empty custom block for inclusion in provider output.
func CustomBlock(comment, indent string) string {
	return CustomBlockWith(comment, indent, indent+comment+" Provider-specific content retained during regeneration.")
}

// CustomBlockWith returns a custom block whose initial content is the given lines.
func CustomBlockWith(comment, indent string, lines ...string) string {
	var b strings.Builder
	b.WriteString(indent + comment + " " + BeginMarker + "\n")
	for _, l := range lines {
		b.WriteString(l + "\n")
	}
	b.WriteString(indent + comment + " " + EndMarker + "\n")
	return b.String()
}

// style is a comment syntax: a prefix and an optional suffix.
type style struct{ start, end string }

func (s style) line(text string) string { return s.start + " " + text + s.end }

func styleOf(f providers.GeneratedFile) style { return style{f.Comment, f.CommentEnd} }

// ErrMalformedCustomBlock reports custom markers that cannot be preserved safely.
var ErrMalformedCustomBlock = errors.New("malformed custom block")

type block struct {
	begin, end int // line indexes of the markers
}

// findBlock locates the custom block by its exact marker lines. Lines that only
// resemble markers are ordinary content: --force keeps a backup of any file it
// replaces, so data safety does not depend on recognizing misspellings.
func findBlock(lines []string, st style) (block, bool, error) {
	b := block{begin: -1, end: -1}
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		switch trimmed {
		case st.line(BeginMarker):
			if b.begin >= 0 {
				return b, false, fmt.Errorf("%w: line %d opens a second custom block", ErrMalformedCustomBlock, i+1)
			}
			b.begin = i
		case st.line(EndMarker):
			if b.begin < 0 {
				return b, false, fmt.Errorf("%w: line %d closes a custom block that was never opened", ErrMalformedCustomBlock, i+1)
			}
			if b.end >= 0 {
				return b, false, fmt.Errorf("%w: line %d closes a second custom block", ErrMalformedCustomBlock, i+1)
			}
			b.end = i
		}
	}
	switch {
	case b.begin < 0:
		return b, false, nil
	case b.end < 0:
		return b, false, fmt.Errorf("%w: the block opened on line %d is never closed", ErrMalformedCustomBlock, b.begin+1)
	}
	return b, true, nil
}

func splitLines(content []byte) []string {
	s := string(content)
	s = strings.TrimSuffix(s, "\n")
	if s == "" {
		return nil
	}
	return strings.Split(s, "\n")
}

func joinLines(lines []string) []byte {
	if len(lines) == 0 {
		return nil
	}
	return []byte(strings.Join(lines, "\n") + "\n")
}

// ExtractCustom returns the lines inside an existing file's custom block.
func ExtractCustom(content []byte, st style) ([]string, bool, error) {
	lines := splitLines(bytes.ReplaceAll(content, []byte("\r\n"), []byte("\n")))
	b, ok, err := findBlock(lines, st)
	if err != nil || !ok {
		return nil, ok, err
	}
	return append([]string{}, lines[b.begin+1:b.end]...), true, nil
}

// unsafeSourceChar matches characters that could end a comment line or form a
// Java \u escape when the source name is written into a header.
var unsafeSourceChar = regexp.MustCompile(`[^A-Za-z0-9._/-]`)

// SafeSource reduces a source name to characters that are inert in every comment syntax.
// Runs of dashes are collapsed because "--" is not allowed inside XML comments.
func SafeSource(source string) string {
	return dashRun.ReplaceAllString(unsafeSourceChar.ReplaceAllString(source, "_"), "-")
}

var dashRun = regexp.MustCompile(`-{2,}`)

// header returns the generated header with the given checksum.
func header(st style, source, sum string) []string {
	return []string{
		st.line(HeaderLine),
		st.line("Source: " + SafeSource(source)),
		st.line(checksumLabel + " " + checksumPrefix + sum),
	}
}

// Checksum hashes content with the checksum value blanked and the custom block's
// inner lines removed, so custom edits never invalidate it.
func Checksum(content []byte, st style) (string, error) {
	lines := splitLines(content)
	b, ok, err := findBlock(lines, st)
	if err != nil {
		return "", err
	}
	if ok {
		lines = append(append([]string{}, lines[:b.begin+1]...), lines[b.end:]...)
	}
	h := sha256.New()
	label := st.start + " " + checksumLabel
	for i, line := range lines {
		if i == 2 && strings.HasPrefix(line, label) {
			line = label
		}
		h.Write([]byte(line))
		h.Write([]byte{'\n'})
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// Pristine reports whether content is a Renvoy-generated file whose recorded
// checksum still matches, meaning nobody edited it outside the custom block.
func Pristine(content []byte, st style) bool {
	lines := splitLines(bytes.ReplaceAll(content, []byte("\r\n"), []byte("\n")))
	if len(lines) < 3 || lines[0] != st.line(HeaderLine) {
		return false
	}
	prefix := st.start + " " + checksumLabel + " " + checksumPrefix
	if !strings.HasPrefix(lines[2], prefix) || !strings.HasSuffix(lines[2], st.end) {
		return false
	}
	recorded := strings.TrimSuffix(strings.TrimPrefix(lines[2], prefix), st.end)
	sum, err := Checksum(joinLines(lines), st)
	return err == nil && sum == recorded
}

// PristineFile reports whether content is an unedited Renvoy-generated version of f.
func PristineFile(content []byte, f providers.GeneratedFile) bool {
	return Pristine(content, styleOf(f))
}

// IsGenerated reports whether content starts with f's generated header.
func IsGenerated(content []byte, f providers.GeneratedFile) bool {
	return strings.HasPrefix(string(content), styleOf(f).line(HeaderLine))
}

// Finalize assembles the final bytes of a generated file. When existing content
// has a custom block, its lines replace the generated block's lines.
func Finalize(f providers.GeneratedFile, source string, existing []byte) ([]byte, error) {
	st := styleOf(f)
	body := splitLines(f.Content)
	generated := joinLines(body)
	if f.YAML {
		if err := singleYAMLDocument(generated); err != nil {
			return nil, fmt.Errorf("internal error: %s output is not valid YAML: %w", f.Path, err)
		}
	}
	var custom []string
	if existing != nil {
		var ok bool
		var err error
		custom, ok, err = ExtractCustom(existing, st)
		if err != nil {
			return nil, err
		}
		if ok {
			b, found, err := findBlock(body, st)
			if err != nil {
				return nil, err
			}
			if !found {
				return nil, fmt.Errorf("%w: the existing file has a custom block but %s output has no place for one",
					ErrMalformedCustomBlock, f.Path)
			}
			body = append(append(append([]string{}, body[:b.begin+1]...), custom...), body[b.end:]...)
		}
	}
	lines := append(header(st, source, ""), body...)
	sum, err := Checksum(joinLines(lines), st)
	if err != nil {
		return nil, err
	}
	lines[2] = header(st, source, sum)[2]
	out := joinLines(lines)
	if len(custom) > 0 {
		if err := checkCustom(f, generated, out, custom); err != nil {
			return nil, fmt.Errorf("%w: %s: %w", ErrMalformedCustomBlock, f.Path, err)
		}
	}
	if len(out) > MaxExistingSize {
		return nil, fmt.Errorf("%s would be %d bytes; generated files are limited to %d", f.Path, len(out), MaxExistingSize)
	}
	return out, nil
}

// checkCustom makes sure custom content can only add to a generated file, never
// change the generated part, so renvoy.yaml stays an accurate description of it.
func checkCustom(f providers.GeneratedFile, generated, combined []byte, custom []string) error {
	text := strings.Join(custom, "\n")
	if !utf8.ValidString(text) {
		return errors.New("the custom block is not valid UTF-8, so tools reading it with other encodings may see different code")
	}
	if f.YAML && strings.Contains(text, "\t") {
		return errors.New("the custom block contains a tab, which YAML parsers handle differently; use spaces")
	}
	// Java, Groovy, and YAML 1.1 parsers treat these as line breaks; the checks
	// below split on \n only, so they could hide a line from them.
	if i := strings.IndexAny(text, "\r\u0085\u2028\u2029"); i >= 0 {
		return fmt.Errorf("the custom block contains the line terminator %q, which parsers disagree on", []rune(text[i:])[0])
	}
	// Invisible format characters (BOM, zero-width, bidi controls) are read
	// differently by parsers and hide what a reviewer sees.
	for _, r := range text {
		if unicode.Is(unicode.Cf, r) {
			return fmt.Errorf("the custom block contains the invisible character %U", r)
		}
	}
	switch {
	case f.YAML:
		if len(text) > MaxCustomBytes {
			return fmt.Errorf("the custom block is %d bytes; at most %d are allowed", len(text), MaxCustomBytes)
		}
		var gen map[string]any
		if err := yaml.Unmarshal(generated, &gen); err != nil {
			return err
		}
		// Check the custom part on its node tree first: decoding into maps checks
		// duplicate keys in quadratic time.
		if err := plainCustomYAML(text, gen, f.CustomKeys); err != nil {
			return err
		}
		if err := singleYAMLDocument(combined); err != nil {
			return fmt.Errorf("the custom block makes the file invalid YAML: %w", err)
		}
		var all map[string]any
		if err := yaml.Unmarshal(combined, &all); err != nil {
			return fmt.Errorf("the custom block makes the file invalid YAML: %w", err)
		}
		for k, v := range gen {
			if !reflect.DeepEqual(all[k], v) {
				return fmt.Errorf("the custom block changes the generated %q section; custom YAML may only add new top-level keys", k)
			}
		}
	case f.Comment == providers.CommentXML:
		if strings.Contains(text, "<?") {
			return errors.New("the custom block may not contain processing instructions")
		}
		for i := strings.Index(text, "<!"); i >= 0; i = nextIndex(text, "<!", i) {
			if !strings.HasPrefix(text[i:], "<!--") && !strings.HasPrefix(text[i:], "<![CDATA[") {
				return errors.New("the custom block may not contain DOCTYPE, ENTITY, ATTLIST, or other declarations")
			}
		}
		// Character references are decoded before Go's checks see them (a
		// surrogate becomes U+FFFD), so check them on the text outside comments
		// and CDATA, where they are literal.
		for _, m := range xmlCharRef.FindAllStringSubmatch(xmlLiteralSections.ReplaceAllString(text, ""), -1) {
			n, err := strconv.ParseInt(strings.TrimPrefix(strings.ToLower(m[1]), "x"), map[bool]int{true: 16, false: 10}[strings.HasPrefix(strings.ToLower(m[1]), "x")], 32)
			if err != nil || !isXMLChar(rune(n)) {
				return fmt.Errorf("the custom block has the character reference &#%s;, which is not a legal XML character", m[1])
			}
		}
		dec := xml.NewDecoder(strings.NewReader("<custom>" + strings.Join(custom, "\n") + "</custom>"))
		dec.Strict = true
		for {
			tok, err := dec.Token()
			if errors.Is(err, io.EOF) {
				break
			} else if err != nil {
				return fmt.Errorf("the custom block is not a well-formed XML fragment: %w", err)
			}
			if err := checkXMLToken(tok); err != nil {
				return err
			}
		}
	case f.Comment == providers.CommentSlash:
		code := strings.Join(custom, "\n")
		// Java (and Groovy) decode \uXXXX before lexing, so an escape can become a
		// newline or a brace that the check below would not see.
		if strings.Contains(code, `\u`) {
			return errors.New(`the custom block contains a \u escape, which the compiler decodes before reading the code`)
		}
		jenkins := path.Base(f.Path) == "Jenkinsfile"
		var top strings.Builder
		usesGString := false
		if err := balanced(code, jenkins, func(c byte, depth int) {
			if depth == 0 {
				top.WriteByte(c)
			}
		}, func(quote, body string) {
			// Groovy evaluates ${...} inside double-quoted strings as code, which
			// the bracket check treats as text. Single-quoted strings are literal.
			if strings.HasPrefix(quote, `"`) && interpolates(body) {
				usesGString = true
			}
		}); err != nil {
			return fmt.Errorf("the custom block could change the generated code around it: %w", err)
		}
		if jenkins && usesGString {
			return errors.New("the custom block uses ${...} in a double-quoted string; use single quotes or concatenation such as 'x' + env.NAME")
		}
		// Only post sections may be added at the top of the pipeline block: any
		// other pipeline-level directive would apply to every generated stage.
		if jenkins && !postOnlyRe.MatchString(top.String()) {
			return errors.New("the custom block may only add post { ... } sections at its top level; pipeline-wide directives apply to every generated stage")
		}
	}
	return nil
}

// plainCustomYAML rejects YAML features that different parsers resolve
// differently (merge keys, anchors, aliases, explicit tags) and top-level keys
// that collide, ignoring case, with generated ones.
func plainCustomYAML(custom string, generated map[string]any, policy providers.CustomKeyPolicy) error {
	var doc yaml.Node
	if err := yaml.Unmarshal([]byte(custom), &doc); err != nil {
		return fmt.Errorf("the custom block is not valid YAML on its own: %w", err)
	}
	nodes := 0
	var walk func(n *yaml.Node) error
	walk = func(n *yaml.Node) error {
		if nodes++; nodes > MaxCustomNodes {
			return fmt.Errorf("the custom block has more than %d YAML nodes", MaxCustomNodes)
		}
		switch {
		case n.Kind == yaml.AliasNode:
			return errors.New("the custom block uses a YAML alias; aliases, anchors, and merge keys are not allowed")
		case n.Anchor != "":
			return errors.New("the custom block uses a YAML anchor; aliases, anchors, and merge keys are not allowed")
		case n.Style&yaml.TaggedStyle != 0:
			return fmt.Errorf("the custom block uses the explicit YAML tag %q, which is not allowed", n.Tag)
		}
		if n.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(n.Content); i += 2 {
				if n.Content[i].Value == "<<" {
					return errors.New("the custom block uses a YAML merge key (<<); aliases, anchors, and merge keys are not allowed")
				}
			}
		}
		for _, c := range n.Content {
			if err := walk(c); err != nil {
				return err
			}
		}
		return nil
	}
	if err := walk(&doc); err != nil {
		return err
	}
	if len(doc.Content) == 1 && doc.Content[0].Kind == yaml.MappingNode {
		top := doc.Content[0]
		for i := 0; i+1 < len(top.Content); i += 2 {
			key := top.Content[i].Value
			if !customKeyRe.MatchString(key) || yaml11Special[strings.ToLower(key)] ||
				strings.EqualFold(key, ".inf") || strings.EqualFold(key, ".nan") {
				return fmt.Errorf("the custom block key %q must be a plain name; YAML 1.1 parsers may read it as a boolean, null, or number", key)
			}
			for k := range generated {
				if strings.EqualFold(strings.TrimSpace(k), strings.TrimSpace(key)) {
					return fmt.Errorf("the custom block redefines the generated %q key", k)
				}
			}
			if len(policy.Allowed) > 0 && !slices.Contains(policy.Allowed, key) {
				return fmt.Errorf("the custom block key %q would apply to the generated jobs; this file's custom block may only add %s",
					key, strings.Join(policy.Allowed, ", "))
			}
			for _, d := range policy.Denied {
				if strings.EqualFold(d, key) {
					return fmt.Errorf("the custom block key %q would apply to the generated jobs; set it in renvoy.yaml instead", key)
				}
			}
		}
	}
	return nil
}

// customKeyRe restricts custom top-level keys to plain names: an optional leading
// dot (GitLab hidden jobs), a letter or underscore, then name characters; job
// names may contain spaces, dots, and colons but not end with a space.
var customKeyRe = regexp.MustCompile(`^\.?[A-Za-z_](?:[A-Za-z0-9_.: -]*[A-Za-z0-9_.:-])?$`)

// postOnlyRe matches top-level custom Jenkinsfile code made only of post sections
// (inner content is excluded, strings and comments are blanked).
var postOnlyRe = regexp.MustCompile(`^\s*(?:post\s*\{\s*)*$`)

// yaml11Special lists plain scalars YAML 1.1 parsers resolve to non-strings.
var yaml11Special = map[string]bool{"y": true, "yes": true, "n": true, "no": true, "on": true, "off": true,
	"true": true, "false": true, "null": true, "~": true}

// singleYAMLDocument parses b and requires exactly one document.
func singleYAMLDocument(b []byte) error {
	dec := yaml.NewDecoder(bytes.NewReader(b))
	var first yaml.Node
	if err := dec.Decode(&first); err != nil {
		return err
	}
	var next yaml.Node
	if err := dec.Decode(&next); err == nil {
		return errors.New("it contains more than one YAML document")
	} else if !errors.Is(err, io.EOF) {
		return err
	}
	return nil
}

// balanced checks that Groovy or Java code has matching brackets outside strings
// and comments, so a custom block cannot close the generated scope it sits in.
// balanced reports unbalanced brackets. When code is non-nil it is called with
// each character outside strings and comments and the bracket depth before it
// (a string is reported as '"' and a comment as a single space).
func balanced(src string, groovy bool, code func(c byte, depth int), onString func(quote, body string)) error {
	if code == nil {
		code = func(byte, int) {}
	}
	if onString == nil {
		onString = func(string, string) {}
	}
	var stack []byte
	closing := map[byte]byte{')': '(', ']': '[', '}': '{'}
	for i := 0; i < len(src); {
		rest := src[i:]
		switch {
		case strings.HasPrefix(rest, "//"):
			end := strings.IndexByte(rest, '\n')
			if end < 0 {
				end = len(rest)
			}
			code(' ', len(stack))
			i += end
		case strings.HasPrefix(rest, "/*"):
			end := strings.Index(rest[2:], "*/")
			if end < 0 {
				return errors.New("unterminated block comment")
			}
			code(' ', len(stack))
			i += end + 4
		case strings.HasPrefix(rest, `"""`), strings.HasPrefix(rest, "'''"):
			q := rest[:3]
			j := 3
			for ; j < len(rest) && !strings.HasPrefix(rest[j:], q); j++ {
				if rest[j] == '\\' {
					j++
				}
			}
			if j >= len(rest) {
				return errors.New("unterminated string")
			}
			onString(q, rest[3:j])
			code('"', len(stack))
			i += j + 3
		case rest[0] == '"' || rest[0] == '\'':
			q := rest[0]
			j := 1
			for ; j < len(rest) && rest[j] != q; j++ {
				if rest[j] == '\\' {
					j++
				}
				if j < len(rest) && rest[j] == '\n' {
					return errors.New("unterminated string")
				}
			}
			if j >= len(rest) {
				return errors.New("unterminated string")
			}
			onString(string(q), rest[1:j])
			code('"', len(stack))
			i += j + 1
		default:
			c := rest[0]
			code(c, len(stack))
			switch c {
			case '(', '[', '{':
				stack = append(stack, c)
			case ')', ']', '}':
				if len(stack) == 0 || stack[len(stack)-1] != closing[c] {
					return fmt.Errorf("unbalanced %q", c)
				}
				stack = stack[:len(stack)-1]
			case '/':
				// In Groovy a bare slash may start a slashy string (/.../ or $/.../$)
				// whose extent depends on context, so it is not allowed there. Java
				// has no slashy strings.
				if groovy {
					return errors.New("a bare '/' (division or a slashy string) is not allowed in Jenkinsfile custom code; use quoted strings")
				}
			}
			i++
		}
	}
	if len(stack) > 0 {
		return fmt.Errorf("unclosed %q", stack[len(stack)-1])
	}
	return nil
}

// MaxCustomBytes and MaxCustomNodes bound the YAML custom content Renvoy checks.
const (
	MaxCustomBytes = 256 << 10
	MaxCustomNodes = 10_000
)

// interpolates reports a ${ in a Groovy double-quoted string body that is not
// escaped with an odd number of backslashes.
func interpolates(body string) bool {
	for i := strings.Index(body, "${"); i >= 0; i = nextIndex(body, "${", i) {
		backslashes := 0
		for j := i - 1; j >= 0 && body[j] == '\\'; j-- {
			backslashes++
		}
		if backslashes%2 == 0 {
			return true
		}
	}
	return false
}

// checkXMLToken keeps pom custom content to what Maven's parser accepts:
// unprefixed names, unique attributes, and legal XML characters.
func checkXMLToken(tok xml.Token) error {
	legal := func(s string) error {
		for _, r := range s {
			if !isXMLChar(r) {
				return fmt.Errorf("the custom block contains %U, which is not allowed in XML", r)
			}
		}
		return nil
	}
	switch t := tok.(type) {
	case xml.StartElement:
		if strings.Contains(t.Name.Local, ":") {
			return fmt.Errorf("the custom block uses ':' in the element name %q, which pom.xml does not support", t.Name.Local)
		}
		if t.Name.Space != "" {
			return fmt.Errorf("the custom block uses the namespace prefix %q, which pom.xml does not declare", t.Name.Space)
		}
		seen := map[string]bool{}
		for _, a := range t.Attr {
			if strings.Contains(a.Name.Local, ":") {
				return fmt.Errorf("the custom block uses ':' in the attribute name %q, which pom.xml does not support", a.Name.Local)
			}
			key := a.Name.Space + ":" + a.Name.Local
			if seen[key] {
				return fmt.Errorf("the custom block repeats the attribute %q", a.Name.Local)
			}
			seen[key] = true
			if a.Name.Space != "" && a.Name.Space != "xmlns" {
				return fmt.Errorf("the custom block uses the namespace prefix %q, which pom.xml does not declare", a.Name.Space)
			}
			if err := legal(a.Value); err != nil {
				return err
			}
		}
	case xml.CharData:
		return legal(string(t))
	case xml.Comment:
		return legal(string(t))
	}
	return nil
}

var (
	// xmlLiteralSections matches comments and CDATA, whose content is literal.
	xmlLiteralSections = regexp.MustCompile(`(?s)<!--.*?-->|<!\[CDATA\[.*?\]\]>`)
	// xmlCharRef finds numeric character references.
	xmlCharRef = regexp.MustCompile(`&#([xX][0-9A-Fa-f]+|[0-9]+);`)
)

// isXMLChar reports characters allowed in XML 1.0 documents.
func isXMLChar(r rune) bool {
	switch {
	case r == 0x9, r == 0xA, r == 0xD:
		return true
	case r >= 0x20 && r <= 0xD7FF, r >= 0xE000 && r <= 0xFFFD, r >= 0x10000 && r <= 0x10FFFF:
		return true
	}
	return false
}

// nextIndex finds the next occurrence of sub in s after position i.
func nextIndex(s, sub string, i int) int {
	j := strings.Index(s[i+1:], sub)
	if j < 0 {
		return -1
	}
	return i + 1 + j
}
